const searches = [
  // 1. Sales Development
  {
    query: '("sales development representative" OR "SDR") SaaS',
    role_category: 'Sales Development',
    location: 'United States'
  },
  {
    query: '("business development representative" OR "BDR") SaaS',
    role_category: 'Sales Development',
    location: 'United States'
  },

  // 2. Sales Expansion and Leadership
  {
    query: '("account executive" OR "sales executive") SaaS',
    role_category: 'Sales Expansion',
    location: 'United States'
  },
  {
    query: '("sales manager" OR "head of sales" OR "director of sales") SaaS',
    role_category: 'Sales Leadership',
    location: 'United States'
  },

  // 3. Revenue Operations and Systems
  {
    query: '("revenue operations" OR "RevOps") SaaS',
    role_category: 'Revenue Operations',
    location: 'United States'
  },
  {
    query: '("sales operations" OR "sales ops") SaaS',
    role_category: 'Revenue Operations',
    location: 'United States'
  },
  {
    query: '("revenue systems" OR "sales systems" OR "revenue technology") SaaS',
    role_category: 'Revenue Systems',
    location: 'United States'
  },

  // 4. CRM and GTM Systems
  {
    query: '("CRM administrator" OR "Salesforce administrator" OR "HubSpot administrator") SaaS',
    role_category: 'CRM Operations',
    location: 'United States'
  },

  // 5. Marketing Operations and Growth
  {
    query: '("marketing operations" OR "marketing ops") SaaS',
    role_category: 'Marketing Operations',
    location: 'United States'
  },
  {
    query: '("marketing automation" OR "marketing automation manager") SaaS',
    role_category: 'Marketing Operations',
    location: 'United States'
  },
  {
    query: '("demand generation" OR "growth marketing" OR "lifecycle marketing") SaaS',
    role_category: 'Growth Marketing',
    location: 'United States'
  },

  // 6. Customer Success and Support Operations
  {
    query: '("customer success manager" OR "customer success operations") SaaS',
    role_category: 'Customer Success',
    location: 'United States'
  },
  {
    query: '("customer support" OR "support operations") SaaS',
    role_category: 'Customer Support',
    location: 'United States'
  },

  // 7. GTM Operations and Leadership
  {
    query: '("GTM engineer" OR "GTM operations" OR "GTM systems") SaaS',
    role_category: 'GTM Operations',
    location: 'United States'
  },
  {
    query: '("head of GTM" OR "director of GTM" OR "GTM strategy") SaaS',
    role_category: 'GTM Leadership',
    location: 'United States'
  }
];

return searches.map((search) => ({
  json: search
}));

const output = [];

for (const item of $input.all()) {
  const response = item.json;
  const jobs = Array.isArray(response.jobs_results)
    ? response.jobs_results
    : [];

  const searchQuery =
    response.search_parameters?.q ??
    response.search_parameters?.query ??
    '';

  const searchLocation =
    response.search_parameters?.location ??
    '';

  for (const job of jobs) {
    output.push({
      json: {
        ...job,
        search_query: searchQuery,
        search_location: searchLocation
      }
    });
  }
}

return output;

const job = $json;

const extensions = Array.isArray(job.extensions)
  ? job.extensions
  : [];

const detected = job.detected_extensions ?? {};

const applyOptions = Array.isArray(job.apply_options)
  ? job.apply_options
  : [];

const firstApplyOption = applyOptions[0] ?? {};

const normalizedTitle = String(job.title ?? '').trim();
const normalizedCompany = String(job.company_name ?? '').trim();

return {
  json: {
    job_id: String(job.job_id ?? '').trim(),

    company_name: normalizedCompany,
    job_title: normalizedTitle,
    location: String(job.location ?? '').trim(),

    posted_at_text: String(
      detected.posted_at ??
      extensions.find(value =>
        /hour|day|week|month|today/i.test(String(value))
      ) ??
      ''
    ).trim(),

    employment_type: String(
      detected.schedule_type ??
      extensions.find(value =>
        /full.?time|part.?time|contract|temporary|intern/i.test(
          String(value)
        )
      ) ??
      ''
    ).trim(),

    remote: Boolean(
      detected.work_from_home ||
      /remote|work from home/i.test(
        `${job.location ?? ''} ${extensions.join(' ')}`
      )
    ),

    source_platform: String(job.via ?? '').trim(),

    job_url: String(
      firstApplyOption.link ??
      job.share_link ??
      ''
    ).trim(),

    description: String(job.description ?? '')
      .replace(/\s+/g, ' ')
      .trim(),

    search_query: String(job.search_query ?? '').trim(),
    search_location: String(job.search_location ?? '').trim(),

    collected_at: new Date().toISOString()
  }
};

const title = String($json.job_title ?? '').toLowerCase();

let roleCategory = null;
let signalCategory = null;

// GTM Operations and Systems
if (
  title.includes('gtm engineer') ||
  title.includes('gtm operations') ||
  title.includes('gtm systems') ||
  title.includes('go-to-market operations') ||
  title.includes('go to market operations')
) {
  roleCategory = 'GTM Operations';
  signalCategory = 'GTM Infrastructure Investment';

// GTM Leadership
} else if (
  title.includes('head of gtm') ||
  title.includes('director of gtm') ||
  title.includes('gtm strategy') ||
  title.includes('head of go-to-market') ||
  title.includes('director of go-to-market')
) {
  roleCategory = 'GTM Leadership';
  signalCategory = 'GTM Transformation';

// Revenue Systems and CRM
} else if (
  title.includes('revenue systems') ||
  title.includes('sales systems') ||
  title.includes('revenue technology')
) {
  roleCategory = 'Revenue Systems';
  signalCategory = 'Revenue Technology Investment';

} else if (
  title.includes('crm administrator') ||
  title.includes('salesforce administrator') ||
  title.includes('hubspot administrator')
) {
  roleCategory = 'CRM Operations';
  signalCategory = 'CRM Infrastructure Investment';

// Revenue Operations
} else if (
  title.includes('revenue operations') ||
  title.includes('sales operations') ||
  title.includes('revops') ||
  title.includes('sales ops')
) {
  roleCategory = 'Revenue Operations';
  signalCategory = 'Revenue Process Complexity';

// Marketing Operations
} else if (
  title.includes('marketing operations') ||
  title.includes('marketing automation') ||
  title.includes('marketing ops')
) {
  roleCategory = 'Marketing Operations';
  signalCategory = 'Marketing Operations Expansion';

// Growth and Demand Generation
} else if (
  title.includes('demand generation') ||
  title.includes('growth marketing') ||
  title.includes('lifecycle marketing') ||
  title.includes('performance marketing')
) {
  roleCategory = 'Growth Marketing';
  signalCategory = 'Demand Generation Expansion';

// Customer Success
} else if (
  title.includes('customer success operations') ||
  title.includes('customer success manager') ||
  title.includes('customer success')
) {
  roleCategory = 'Customer Success';
  signalCategory = 'Customer Lifecycle Expansion';

// Customer Support
} else if (
  title.includes('customer support') ||
  title.includes('support operations') ||
  title.includes('technical support')
) {
  roleCategory = 'Customer Support';
  signalCategory = 'Support Volume Expansion';

// Sales Leadership
} else if (
  title.includes('sales manager') ||
  title.includes('head of sales') ||
  title.includes('director of sales') ||
  title.includes('vp of sales') ||
  title.includes('vice president of sales')
) {
  roleCategory = 'Sales Leadership';
  signalCategory = 'Sales Team Expansion';

// Account Executives
} else if (
  title.includes('account executive') ||
  title.includes('sales executive')
) {
  roleCategory = 'Sales Expansion';
  signalCategory = 'Sales Capacity Expansion';

// SDR and BDR
} else if (
  title.includes('sales development representative') ||
  title.includes('business development representative') ||
  title.includes('sales development') ||
  /\bsdr\b/.test(title) ||
  /\bbdr\b/.test(title)
) {
  roleCategory = 'Sales Development';
  signalCategory = 'Outbound Sales Expansion';
}

return {
  json: {
    ...$json,
    is_target_role: Boolean(roleCategory),
    role_category: roleCategory,
    signal_category: signalCategory
  }
};

const company = String($json.company_name ?? '')
  .toLowerCase()
  .replace(/[^a-z0-9]/g, '');

const title = String($json.job_title ?? '')
  .toLowerCase()
  .replace(/[^a-z0-9]/g, '');

return {
  json: {
    ...$json,
    deduplication_key: `${company}-${title}`
  }
};

const description = String($json.description ?? '');

return {
  json: {
    'Company Name': $json.company_name ?? '',
    'Job Title': $json.job_title ?? '',
    'Role Category': $json.role_category ?? '',
    'Signal Category': $json.signal_category ?? '',

    'Job Location': $json.location ?? '',
    'Remote': $json.remote ?? false,
    'Employment Type': $json.employment_type ?? '',
    'Posted': $json.posted_at_text ?? '',

    'Source Platform': $json.source_platform ?? '',
    'Job URL': $json.job_url ?? '',

    'Job Description':
      description.length > 500
        ? `${description.slice(0, 500)}...`
        : description
  }
};

const errors = [];

const jobTitle = String($json.job_title ?? '').trim();
const companyName = String($json.company_name ?? '').trim();
const jobUrl = String($json.job_url ?? '').trim();

if (!jobTitle) {
  errors.push('Missing job title');
}

if (!companyName) {
  errors.push('Missing company name');
}

if (!jobUrl) {
  errors.push('Missing job URL');
}

return {
  json: {
    ...$json,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    validation_errors: errors,
    is_valid_job: errors.length === 0
  }
};

return {
  json: {
    timestamp: new Date().toISOString(),
    reason: $json.validation_errors,
    company: $json.company_name,
    title: $json.job_title,
    url: $json.job_url
  }
};

const fileItem = $input.first();

const validJobCount = $('Prepare CSV Rows').all().length;

return [
  {
    json: {
      pipeline_status: 'SUCCESS',
      message: 'Hiring signal pipeline completed successfully.',
      valid_jobs_exported: validJobCount,
      output_file: 'hiring_signals.csv',
      completed_at: new Date().toISOString()
    },

    // Preserve the generated CSV file
    binary: fileItem.binary ?? {}
  }
];
